## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/aplasticAnemiaLogic.ts`

```typescript
// ─────────────────────────────────────────────────────────────────────────────
// Aplastic Anemia (AA) Pathway Logic Engine
// Sources:
//   ASH 2022 Guidelines for Aplastic Anemia (Bhatt VR et al., Blood Adv 2022, PMID 35255491)
//   EBMT/EHA Severe Aplastic Anemia Guidelines 2024
//   NCCN Guidelines: Aplastic Anemia v1.2025
//   Eltrombopag + IST: Townsley DM et al., NEJM 2017, PMID 28564562
//   Imetelstat in AA: Townsley et al., 2024
//   Danazol in AA: Townsley DM et al., NEJM 2016, PMID 27959701
// ─────────────────────────────────────────────────────────────────────────────

// ─── Types ────────────────────────────────────────────────────────────────────
export type AASeverity = "non_severe" | "severe" | "very_severe";
export type AAEtiology =
  | "idiopathic"
  | "immune_mediated"
  | "inherited" // Fanconi, dyskeratosis congenita, Diamond-Blackfan
  | "drug_induced"
  | "viral"
  | "pregnancy_related"
  | "unknown";

export type AAInheritedType =
  | "fanconi_anemia"
  | "dyskeratosis_congenita"
  | "diamond_blackfan"
  | "shwachman_diamond"
  | "other_inherited"
  | "none";

export type DonorAvailability =
  | "hla_matched_sibling" // Best option
  | "matched_unrelated_10_10" // MUD 10/10
  | "matched_unrelated_8_8" // MUD 8/8
  | "haploidentical" // Haplo-HCT
  | "none";

export interface AplasticAnemiaInput {
  // Patient profile
  age: number;
  ecogPS: 0 | 1 | 2 | 3 | 4;

  // Disease characterization
  severity: AASeverity;
  etiology: AAEtiology;
  inheritedType: AAInheritedType;

  // Lab values
  anc: number; // Absolute neutrophil count (cells/µL)
  reticulocytes: number; // Absolute reticulocyte count (cells/µL)
  platelets: number; // Platelets (×10³/µL)
  hemoglobin: number; // g/dL

  // Clonal evolution markers
  hasPNHClone: boolean; // PNH clone detected
  hasMDSFeatures: boolean; // Dysplasia or cytogenetic abnormalities
  hasClonalCytogenetics: boolean; // Monosomy 7, del(5q), complex karyotype
  hasSF3B1OrOtherMDSMutation: boolean; // Somatic mutations (DNMT3A, ASXL1, etc.)
  hasTelomereDisease: boolean; // Short telomeres / telomeropathy

  // Treatment context
  priorIST: boolean; // Prior immunosuppressive therapy (hATG + CsA)
  priorEltrombopag: boolean;
  priorHCT: boolean;
  donorAvailability: DonorAvailability;
  patientPreference: "aggressive" | "moderate" | "bsc";

  // Response assessment (if applicable)
  priorISTResponse: "complete" | "partial" | "no_response" | "relapse" | "na";
}

export type TreatmentRecommendation =
  | "hct_msd_first_line" // Allo-HCT with MSD — first-line for young patients
  | "ist_hatg_csa_eltro" // hATG + CsA + Eltrombopag — first-line IST
  | "ist_hatg_csa" // hATG + CsA (without eltrombopag)
  | "hct_mud" // Allo-HCT with MUD — second-line or older patients without MSD
  | "hct_haplo" // Haploidentical HCT
  | "second_line_ist" // Second-line IST (rATG or alemtuzumab)
  | "eltrombopag_mono" // Eltrombopag monotherapy (non-severe or refractory)
  | "danazol" // Danazol for telomeropathy
  | "supportive_transfusion" // Transfusion support ± growth factors
  | "watch_wait" // Non-severe AA: watch and wait
  | "clinical_trial"
  | "bsc_only";

export interface AplasticAnemiaResult {
  primaryRecommendation: TreatmentRecommendation;
  primaryLabel: string;
  primaryRationale: string;
  transplantRecommendation: string;
  transplantRationale: string;
  secondLineOptions: string[];
  monitoringPlan: string[];
  keyWarnings: string[];
  urgencyFlag: "routine" | "urgent" | "emergent";
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
export function classifyAASeverity(input: Pick<AplasticAnemiaInput, "anc" | "reticulocytes" | "platelets">): AASeverity {
  const hypocellularBM = true; // Assumed from clinical context
  if (!hypocellularBM) return "non_severe";

  // Camitta criteria
  const severeCount = [
    input.anc < 500,
    input.reticulocytes < 20000,
    input.platelets < 20,
  ].filter(Boolean).length;

  if (input.anc < 200) return "very_severe"; // vSAA: ANC <200
  if (severeCount >= 2) return "severe"; // SAA: ≥2 of 3 criteria
  return "non_severe";
}

export function getSeverityLabel(severity: AASeverity): string {
  const map: Record<AASeverity, string> = {
    non_severe: "Non-Severe AA",
    severe: "Severe AA (SAA)",
    very_severe: "Very Severe AA (vSAA)",
  };
  return map[severity];
}

export function getSeverityColor(severity: AASeverity): string {
  const map: Record<AASeverity, string> = {
    non_severe: "bg-yellow-900/30 border-yellow-600/50 text-yellow-300",
    severe: "bg-orange-900/30 border-orange-600/50 text-orange-300",
    very_severe: "bg-red-900/30 border-red-600/50 text-red-300",
  };
  return map[severity];
}

// ─── Core Logic ───────────────────────────────────────────────────────────────
export function assessAplasticAnemia(input: AplasticAnemiaInput): AplasticAnemiaResult {
  const keyWarnings: string[] = [];
  const monitoringPlan: string[] = [];
  const secondLineOptions: string[] = [];

  // ── BSC ──────────────────────────────────────────────────────────────────
  if (input.patientPreference === "bsc" || input.ecogPS === 4) {
    return {
      primaryRecommendation: "bsc_only",
      primaryLabel: "Best Supportive Care",
      primaryRationale: "Transfusion support, infection prophylaxis, and growth factors as needed. Goals-of-care discussion documented.",
      transplantRecommendation: "Not indicated",
      transplantRationale: "BSC intent.",
      secondLineOptions: [],
      monitoringPlan: ["CBC with differential every 2–4 weeks", "Transfusion support as needed"],
      keyWarnings: ["Ensure goals-of-care discussion is documented."],
      urgencyFlag: "routine",
    };
  }

  // ── Inherited AA — special considerations ────────────────────────────────
  if (input.inheritedType !== "none" && input.etiology === "inherited") {
    if (input.inheritedType === "fanconi_anemia") {
      keyWarnings.push("Fanconi Anemia: Avoid standard conditioning regimens — use FA-specific reduced-intensity conditioning (fludarabine-based). Androgen therapy (danazol/oxymetholone) may provide temporary benefit. HCT is curative but requires FA-specific protocols.");
    }
    if (input.inheritedType === "dyskeratosis_congenita") {
      keyWarnings.push("Dyskeratosis Congenita / Telomeropathy: Danazol (androgen) can improve blood counts (Townsley DM et al., NEJM 2016). HCT has high risk of pulmonary/hepatic toxicity — use reduced-intensity conditioning. Screen family members for telomere disease.");
    }
    if (input.hasTelomereDisease) {
      keyWarnings.push("Short telomeres detected: Consider danazol therapy. Standard IST (hATG+CsA) has lower response rates in telomeropathy. HCT conditioning must be modified.");
    }
  }

  // ── Clonal evolution warnings ─────────────────────────────────────────────
  if (input.hasClonalCytogenetics) {
    keyWarnings.push("Clonal cytogenetics (monosomy 7, del(5q), or complex): High risk of MDS/AML transformation. Allo-HCT is strongly recommended over IST.");
  }
  if (input.hasMDSFeatures) {
    keyWarnings.push("MDS features on bone marrow biopsy: Reclassify as hypoplastic MDS. HCT is preferred over IST.");
  }
  if (input.hasSF3B1OrOtherMDSMutation) {
    keyWarnings.push("Somatic mutations (DNMT3A, ASXL1, SF3B1, etc.): Monitor for clonal evolution. Does not preclude IST but warrants closer surveillance.");
  }

  // ── PNH clone ─────────────────────────────────────────────────────────────
  if (input.hasPNHClone) {
    monitoringPlan.push("PNH clone detected: Monitor PNH clone size every 6 months. If clone >50% or thrombosis occurs, consider eculizumab.");
  }

  // ── Non-severe AA ─────────────────────────────────────────────────────────
  if (input.severity === "non_severe") {
    if (!input.priorIST) {
      return {
        primaryRecommendation: "watch_wait",
        primaryLabel: "Watch and Wait ± Supportive Care",
        primaryRationale: "Non-severe AA without transfusion dependence: Observe with CBC monitoring every 4–8 weeks. Initiate treatment if progression to SAA/vSAA or transfusion dependence develops. Eltrombopag monotherapy is an option for transfusion-dependent non-severe AA.",
        transplantRecommendation: "Not indicated for non-severe AA unless progression to SAA.",
        transplantRationale: "Allo-HCT is reserved for SAA/vSAA or refractory disease.",
        secondLineOptions: ["Eltrombopag monotherapy if transfusion-dependent", "IST (hATG + CsA) if progression to SAA"],
        monitoringPlan: ["CBC with differential every 4–8 weeks", "Bone marrow biopsy if progression suspected", "PNH flow cytometry every 6–12 months", ...monitoringPlan],
        keyWarnings,
        urgencyFlag: "routine",
      };
    }
  }

  // ── SAA/vSAA — First-line ─────────────────────────────────────────────────
  if (!input.priorIST && (input.severity === "severe" || input.severity === "very_severe")) {
    // Young patient (<40) with MSD — HCT first-line
    if (input.age < 40 && input.donorAvailability === "hla_matched_sibling") {
      return {
        primaryRecommendation: "hct_msd_first_line",
        primaryLabel: "Allo-HCT with HLA-Matched Sibling Donor (MSD) — First-Line",
        primaryRationale: "ASH 2022 / EBMT 2024: For patients <40 years with SAA/vSAA and an available HLA-matched sibling donor, allo-HCT is the preferred first-line treatment. 5-year OS >90% with MSD-HCT in young patients. Cyclophosphamide + ATG conditioning is standard.",
        transplantRecommendation: "Proceed to allo-HCT with MSD as soon as possible. Target <3 months from diagnosis to transplant.",
        transplantRationale: "Delay in HCT increases transfusion burden and infection risk. Minimize transfusions before HCT to reduce alloimmunization.",
        secondLineOptions: ["IST (hATG + CsA + eltrombopag) if HCT is delayed or patient declines", "MUD-HCT if MSD unavailable"],
        monitoringPlan: ["Minimize blood product transfusions (use irradiated, leukoreduced products)", "Infection prophylaxis (antifungal, antibacterial, antiviral)", "HLA typing of patient and siblings", ...monitoringPlan],
        keyWarnings: [...keyWarnings, "Minimize transfusions before HCT to reduce alloimmunization. Use leukoreduced, irradiated blood products.", "Avoid family member blood products (risk of alloimmunization to potential donor antigens)."],
        urgencyFlag: "urgent",
      };
    }

    // Age 40–60 with MSD — HCT vs IST discussion
    if (input.age >= 40 && input.age < 60 && input.donorAvailability === "hla_matched_sibling") {
      return {
        primaryRecommendation: "ist_hatg_csa_eltro",
        primaryLabel: "hATG + CsA + Eltrombopag (First-Line IST) — MSD-HCT Alternative",
        primaryRationale: "For patients 40–60 with MSD: Both IST and MSD-HCT are reasonable first-line options. EBMT 2024 recommends MSD-HCT up to age 50–60 in fit patients; ASH 2022 recommends IST for patients >40 with MSD. Discuss both options with patient. If IST chosen: hATG (horse ATG) + CsA + eltrombopag (NEJM 2017, PMID 28564562) — 94% response rate at 6 months.",
        transplantRecommendation: "MSD-HCT is a viable first-line option for fit patients 40–60. If IST chosen, proceed to MSD-HCT if no response at 3–6 months.",
        transplantRationale: "MSD-HCT outcomes are excellent even in patients 40–60. Discuss transplant vs IST based on patient preference, comorbidities, and institutional experience.",
        secondLineOptions: ["MSD-HCT if IST fails (no response at 3–6 months)", "MUD-HCT if MSD-HCT not pursued and IST fails"],
        monitoringPlan: ["CBC at 1, 2, 3, 6 months after IST", "CsA levels every 2 weeks initially", "Bone marrow biopsy at 3–6 months if no response", ...monitoringPlan],
        keyWarnings: [...keyWarnings, "hATG (horse ATG, ATGAM) is preferred over rATG (rabbit ATG, Thymoglobulin) for first-line SAA (NEJM 2011, PMID 21345103).", "Eltrombopag must be started on Day 14 of hATG/CsA (not Day 1) to avoid early hepatotoxicity."],
        urgencyFlag: "urgent",
      };
    }

    // No MSD, age <40 — IST first, then MUD-HCT if IST fails
    if (input.donorAvailability !== "hla_matched_sibling" && input.age < 40) {
      return {
        primaryRecommendation: "ist_hatg_csa_eltro",
        primaryLabel: "hATG + CsA + Eltrombopag (First-Line IST)",
        primaryRationale: "No MSD available: hATG + CsA + eltrombopag is first-line IST. NEJM 2017 (PMID 28564562): 94% overall response rate at 6 months with triple therapy. Initiate MUD search simultaneously — proceed to MUD-HCT if no response at 3–6 months.",
        transplantRecommendation: "Initiate unrelated donor search immediately. Proceed to MUD-HCT (10/10 preferred) if no response to IST at 3–6 months.",
        transplantRationale: "MUD-HCT outcomes in SAA have improved significantly with fludarabine-based conditioning. 5-year OS ~75–80% with MUD-HCT after IST failure.",
        secondLineOptions: ["MUD-HCT (10/10) if IST fails", "Haploidentical HCT if MUD unavailable", "Eltrombopag continuation if partial response"],
        monitoringPlan: ["CBC at 1, 2, 3, 6 months after IST", "CsA levels every 2 weeks", "Bone marrow biopsy at 3–6 months", "Unrelated donor search initiated at diagnosis", ...monitoringPlan],
        keyWarnings: [...keyWarnings, "hATG preferred over rATG for first-line SAA.", "Start eltrombopag on Day 14 (not Day 1) of hATG/CsA."],
        urgencyFlag: "urgent",
      };
    }

    // Older adult (≥60) or unfit — IST preferred
    if (input.age >= 60 || input.ecogPS >= 2) {
      return {
        primaryRecommendation: "ist_hatg_csa_eltro",
        primaryLabel: "hATG + CsA + Eltrombopag (First-Line IST)",
        primaryRationale: "Older adults (≥60) or unfit patients: IST (hATG + CsA + eltrombopag) is preferred over HCT due to higher transplant-related mortality. Response rates remain high (~80–90%). Eltrombopag addition improves response rates and speed.",
        transplantRecommendation: input.donorAvailability !== "none"
          ? "Reduced-intensity conditioning (RIC) allo-HCT is an option for fit patients ≥60 with available donor after IST failure."
          : "Allo-HCT not recommended for patients ≥60 without available donor or with significant comorbidities.",
        transplantRationale: "RIC allo-HCT in selected patients ≥60 has improved outcomes with fludarabine-based conditioning.",
        secondLineOptions: ["Eltrombopag monotherapy if IST contraindicated", "RIC allo-HCT if IST fails and patient is fit", "Danazol for telomeropathy"],
        monitoringPlan: ["CBC monthly for 6 months, then every 2–3 months", "CsA levels every 2 weeks initially", "Bone marrow biopsy at 6 months", ...monitoringPlan],
        keyWarnings: [...keyWarnings, "Monitor for cyclosporine nephrotoxicity and hypertension in older patients.", "Eltrombopag hepatotoxicity: Monitor LFTs monthly."],
        urgencyFlag: "urgent",
      };
    }
  }

  // ── Refractory / Relapsed SAA ─────────────────────────────────────────────
  if (input.priorIST && (input.severity === "severe" || input.severity === "very_severe")) {
    if (input.priorISTResponse === "no_response" || input.priorISTResponse === "relapse") {
      // Has donor — HCT
      if (input.donorAvailability !== "none" && !input.priorHCT) {
        const rec: TreatmentRecommendation =
          input.donorAvailability === "hla_matched_sibling" ? "hct_msd_first_line" :
          input.donorAvailability === "haploidentical" ? "hct_haplo" : "hct_mud";

        return {
          primaryRecommendation: rec,
          primaryLabel: input.donorAvailability === "hla_matched_sibling"
            ? "Allo-HCT with MSD (Second-Line)"
            : input.donorAvailability === "haploidentical"
            ? "Haploidentical HCT (Post-IST Failure)"
            : "Allo-HCT with MUD (Second-Line)",
          primaryRationale: "IST failure or relapse: Allo-HCT is the treatment of choice. Second-line IST (rATG or alemtuzumab) is an alternative if HCT is not feasible. EBMT 2024: Proceed to MUD-HCT without delay after IST failure.",
          transplantRecommendation: "Proceed to allo-HCT. Fludarabine-based conditioning (Flu/Cy/ATG) is preferred for MUD-HCT.",
          transplantRationale: "Second-line IST response rates are lower (~30–40%). HCT offers the best chance of long-term cure after IST failure.",
          secondLineOptions: ["Second-line IST (rATG + CsA ± eltrombopag) if HCT not feasible", "Eltrombopag monotherapy for partial responders"],
          monitoringPlan: ["Proceed to transplant evaluation immediately", "Infection prophylaxis and transfusion support", ...monitoringPlan],
          keyWarnings: [...keyWarnings, "Haploidentical HCT with post-transplant cyclophosphamide (PTCy) is increasingly used when MSD/MUD unavailable."],
          urgencyFlag: "urgent",
        };
      }

      // No donor or prior HCT — second-line IST or eltrombopag
      return {
        primaryRecommendation: "second_line_ist",
        primaryLabel: "Second-Line IST (rATG + CsA ± Eltrombopag) or Eltrombopag Monotherapy",
        primaryRationale: "No available donor or prior HCT: Second-line IST with rATG (rabbit ATG, Thymoglobulin) + CsA ± eltrombopag. Response rate ~30–40%. Eltrombopag monotherapy (Townsley DM et al., NEJM 2017) achieved trilineage response in 40% of refractory SAA patients.",
        transplantRecommendation: "Haploidentical HCT should be explored if no prior HCT and response to second-line IST is inadequate.",
        transplantRationale: "Haplo-HCT with PTCy has improved outcomes and is now a viable option when MSD/MUD unavailable.",
        secondLineOptions: ["Eltrombopag monotherapy (150 mg/day)", "Haploidentical HCT with PTCy", "Clinical trial (imetelstat, luspatercept, novel agents)"],
        monitoringPlan: ["CBC every 4 weeks", "Bone marrow biopsy at 3–6 months", "Monitor for clonal evolution (cytogenetics, NGS)", ...monitoringPlan],
        keyWarnings: [...keyWarnings, "Monitor for clonal evolution (monosomy 7) with repeat bone marrow biopsy every 6–12 months.", "Eltrombopag: Monitor LFTs monthly. Discontinue if ALT >3× ULN."],
        urgencyFlag: "urgent",
      };
    }

    // Partial response — continue/optimize
    if (input.priorISTResponse === "partial") {
      return {
        primaryRecommendation: "eltrombopag_mono",
        primaryLabel: "Eltrombopag Optimization / Continuation",
        primaryRationale: "Partial response to IST: Continue CsA and add/optimize eltrombopag (150 mg/day) if not already included. Reassess at 3–6 months. If no improvement, proceed to second-line IST or HCT.",
        transplantRecommendation: input.donorAvailability !== "none" ? "Consider allo-HCT if response is inadequate at 6 months." : "Optimize medical therapy; explore haploidentical HCT.",
        transplantRationale: "Partial response may be sufficient for some patients; full CR is the goal.",
        secondLineOptions: ["Add eltrombopag if not already included", "Second-line IST (rATG) if no improvement", "HCT if donor available"],
        monitoringPlan: ["CBC every 4–8 weeks", "CsA levels monthly", "Bone marrow biopsy at 6 months", ...monitoringPlan],
        keyWarnings,
        urgencyFlag: "routine",
      };
    }
  }

  // Fallback
  return {
    primaryRecommendation: "clinical_trial",
    primaryLabel: "Clinical Trial / Specialist Consultation",
    primaryRationale: "Consult hematology specialist for personalized recommendation.",
    transplantRecommendation: "Assess after complete evaluation.",
    transplantRationale: "Transplant decision requires complete risk stratification.",
    secondLineOptions: [],
    monitoringPlan: ["CBC with differential every 4 weeks", "Bone marrow biopsy as clinically indicated"],
    keyWarnings,
    urgencyFlag: "routine",
  };
}
